{
  "probability": 0.69,
  "range_low": 0.60,
  "range_high": 0.78,
  "summary": [
    "Anchored on historical two-thirds-majority frequency (~0.56) and updated to a 0.69 posterior using current polls and coalition dynamics.",
    "Opposition consolidation around TISZA increases the odds of reaching 133 seats, providing a meaningful up-factor.",
    "Our Homeland entering Parliament and continued poll fragmentation press probability downward as fragmentation complicates coalitions.",
    "Structural bias of Hungary's winner-takes-most system and turnout uncertainty dampen the chance of a persistent two-thirds majority, despite occasional regime-change signals."
  ],
  "confidence": "medium",
  "narrative": "Starting from the historical baseline, the 2026 race shows mixed polls and shifting coalitions. After applying the updates, the balance tilts toward a non-negligible chance of a two-thirds outcome for some bloc, but with substantial uncertainty due to turnout and fragmentation; the calibrated posterior sits at 0.69 with a wide but plausible range.",
  "justification": {
    "anchor": {
      "probability": 0.56,
      "basis": "Historical frequency of constitutional two-thirds majorities in Hungary (approx. 4 of 9 post-1990 elections), supporting a baseline around 0.56 for a 2/3 outcome."
    },
    "factor_updates": [
      {
        "factor": "Opposition coalition consolidation around TISZA",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Media reports in early 2026 show increasing talk of a united anti-Fidesz bloc around TISZA, which could plausibly reach the 133-seat threshold if turnout is favorable."
      },
      {
        "factor": "Our Homeland entering parliament",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Forecasts suggest Our Homeland crossing the threshold, which fragments the anti-Fidesz vote and reduces clean coalition math toward 2/3."
      },
      {
        "factor": "Divergent polls and forecast uncertainty",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Consistent polling divergence lowers confidence in a persistent path to 2/3 for any bloc."
      },
      {
        "factor": "Electoral-system structural bias toward large parties",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "The win-by-margin configuration tends to translate mid-40s to mid-50s in votes into near-2/3 of seats for the leading bloc, complicating cross-coalition paths to 2/3."
      },
      {
        "factor": "Market/regime-change signals",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Investor expectations of regime-change risk keep the possibility alive that a unified bloc could emerge in a new configuration, elevating 2/3 prospects modestly."
      }
    ],
    "synthesis_rationale": "The posterior of 0.69 results from starting with a moderate historical anchor (0.56) and incorporating multiple updates that together tilt toward a nonzero probability of a 2/3 outcome but not with high confidence. The strongest negative factor is structural bias, tempered by potential opposition consolidation and market-change signals; turnout and fragmentation inject substantial calibration uncertainty, producing a calibrated range around the point estimate."
  }
}

{
  "probability": 0.69,
  "range_low": 0.62,
  "range_high": 0.75,
  "summary": [
    "Early-2026 polling shows a competitive race with no durable consensus on a two-thirds outcome for any party or coalition.",
    "Opposition consolidation around TISZA could enable a pre-electoral bloc to reach 133 seats, increasing the possibility of a 2/3 majority under favorable turnout.",
    "Our Homeland entering parliament adds fragmentation, which dampens the odds of a single bloc achieving 133 seats.",
    "Structural bias in Hungary's winner-takes-most system reduces the likelihood of a stable 2/3 majority despite potential coalitions and shifting vote shares."
  ],
  "confidence": "medium",
  "narrative": "A Bayesian update from a historical baseline of roughly 44% to a posterior of 69% reflects mixed signals: opposition consolidation provides upside potential, while fragmentation and the electoral system’s structural bias push against a clean 2/3 outcome. The calibrated range acknowledges substantial turnout and polling uncertainty despite the central estimate.”
  ,
  "justification": {
    "anchor": {
      "probability": 0.44,
      "basis": "Historical base rate of achieving a two-thirds (constitutional) majority in Hungary's National Assembly under the current winner-takes-most system, with 4 of 9 post-1990 elections producing a 2/3 majority."
    },
    "factor_updates": [
      {
        "factor": "Opposition coalition consolidation around TISZA and potential partners",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Polls in early 2026 show TISZA gaining ground and discussions about a united anti-Fidesz front; a credible pre-electoral coalition could plausibly reach the 133-seat threshold."
      },
      {
        "factor": "Our Homeland entering parliament and increased fragmentation",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Forecasts indicate Our Homeland may cross the threshold, adding to fragmentation and lowering the probability that a single party or pre-electoral coalition can reach 133 seats."
      },
      {
        "factor": "Divergent polls and uncertain forecasts in early 2026",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Polls show mixed leads across surveys, reducing confidence in a stable path to 2/3 and increasing forecast uncertainty."
      },
      {
        "factor": "Electoral-system bias toward large parties (structural advantage for Fidesz)",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Winner-takes-most design tends to convert mid-40s to mid-50s vote shares into 67–68% of seats, dampening the odds of any bloc reaching a 2/3 majority."
      },
      {
        "factor": "Market expectations of regime-change risk and investor sentiment",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Signals of potential regime change can shift incentives and calculations toward scenarios where a 2/3 is achieved, even if not guaranteed."
      },
      {
        "factor": "Turnout dynamics and mobilization",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Uncertain turnout can swing seat shares in unpredictable ways, keeping the 2/3 question unresolved."
      }
    ],
    "synthesis_rationale": "Starting from a 0.44 anchor, the strongest updates push upward (opposition consolidation, regime-change signals) but are tempered by fragmentation and structural bias that tend to suppress a guaranteed 2/3 result. The net calibration yields a posterior around 0.69, with a range reflecting substantial remaining uncertainty about turnout and coalition dynamics."
  }
}

