      {
        "factor": "Divergent polls and uncertain forecasts in early 2026",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Mixed leads across multiple polls undermine a durable path to 2/3 and reduce forecast reliability."
      },
      {
        "factor": "Opposition coalition consolidation around TISZA",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "A credible pre-electoral bloc could collectively reach 133 seats, increasing the chance a bloc achieves 2/3 if coalitions cohere."
      },
      {
        "factor": "Our Homeland entering parliament (fragmentation)",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Entry of another party fragments anti-Fidesz support and complicates reaching 133 seats for a single bloc."
